# -*- coding: utf-8 -*-
"""Поиск местоимений в собранном документе."""
import re, sys, docx

STRICT = """
я меня мне мной мною ты тебя тебе тобой он она оно они его её ее их ему ей им ими
нём нем ней ним ними них нее неё него мы нас нам нами вы вас вам вами
себя себе собой собою
мой моя моё мои моего моей моих моим моими твой наш наша наше наши нашего нашей
наших нашим нашими ваш ваша ваше ваши вашего вашей ваших вашим вашими
свой своя своё свои своего своей своих своим своими своему свою
этот эта эти этого этой этом этих этим этими эту
тот та те того той том тех тем теми ту
такой такая такое такие такого таких таким такими такую таков такова таковы столько
сам сама само сами самого самой самих самим самими саму
весь вся всей всю всякий всякая всякие всяких
каждый каждая каждое каждые каждого каждой каждом каждых каждым
любой любая любое любые любого любых любым иной иная иное иные иного иных
другой другая другое другие другого других другим другими другую
кто кого кому кем ком какой какая какое какие какого каких каким какими каков каковы
который которая которое которые которого которой котором которых которым которыми которую
чей чья чьё чьи сколько
некто нечто некоторый некоторые некоторых некоторым несколько некий некая некие
никто никого никому никем ничто ничего ничему ничем никакой никакая никакие
никаких никаким ничей
"""
AMBIGUOUS = "что чего чему чем чём то всё все всего всех всем всеми"

strict = set(STRICT.split())
ambig = set(AMBIGUOUS.split())

d = docx.Document(sys.argv[1] if len(sys.argv) > 1 else "../Пояснительная_записка.docx")
chunks = [p.text for p in d.paragraphs]
for t in d.tables:
    for r in t.rows:
        for c in r.cells:
            chunks.append(c.text)

hits_s, hits_a = {}, {}
for text in chunks:
    for w in re.findall(r"[А-Яа-яЁё]+(?:-[а-яё]+)?", text):
        lw = w.lower()
        if lw in strict:
            hits_s.setdefault(lw, []).append(text.strip()[:100])
        elif lw in ambig:
            hits_a.setdefault(lw, []).append(text.strip()[:100])

print("=== МЕСТОИМЕНИЯ (убрать) ===")
if not hits_s:
    print("  не найдено")
for w, ex in sorted(hits_s.items(), key=lambda x: -len(x[1])):
    print(f"  {w} ({len(ex)}): {ex[0]}")

print("\n=== СЛОВА-ОМОНИМЫ (проверить вручную: союз или местоимение) ===")
for w, ex in sorted(hits_a.items(), key=lambda x: -len(x[1])):
    print(f"  {w}: {len(ex)} вхожд.")
